const ResetDevice=(()=>{const e=window.NKA_API_BASE||"/api";async function t(){const t=localStorage.getItem("nka_token");if(t)try{await fetch(`${e}/device`,{method:"DELETE",headers:{Authorization:`Bearer ${t}`}})}catch(e){}localStorage.clear();try{const e=await caches.keys();await Promise.all(e.map(e=>caches.delete(e)))}catch(e){}try{await new Promise(e=>{const t=indexedDB.deleteDatabase("nka-offline-cache");t.onsuccess=t.onerror=t.onblocked=()=>e()})}catch(e){}location.reload()}return{openConfirm:function(){const e=document.createElement("div");e.className="reset-overlay",e.innerHTML='\n      <div class="reset-modal" role="alertdialog" aria-modal="true" aria-labelledby="reset-title">\n        <div class="reset-icon">⚠️</div>\n        <h3 id="reset-title">Réinitialiser cet appareil ?</h3>\n        <p>Les données locales de cet appareil seront effacées (PIN, comptes, cache). Les bulletins restent disponibles sur vos autres appareils. Cette action est irréversible.</p>\n        <div class="reset-actions">\n          <button class="btn btn-outline" id="reset-cancel-btn">Annuler</button>\n          <button class="btn btn-danger" id="reset-confirm-btn">Réinitialiser</button>\n        </div>\n      </div>\n    ',document.body.appendChild(e);const n=()=>e.remove();e.addEventListener("click",t=>{t.target===e&&n()}),e.querySelector("#reset-cancel-btn").addEventListener("click",n),e.querySelector("#reset-confirm-btn").addEventListener("click",async()=>{const n=e.querySelector("#reset-confirm-btn");n.disabled=!0,n.textContent="Réinitialisation...",await t()})},resetDevice:t}})();